insert into services (id, name, category, description, price_basis, price_min, price_max, price_note, typical_duration_minutes, requires_survey, keywords) values
  ('svc_boiler_service', 'Annual gas boiler service', 'heating', 'Full annual service and safety check of a gas boiler, including flue gas analysis and a written service record. Keeps the manufacturer warranty valid.', 'fixed', 95, 95, 'Fixed price per boiler.', 60, false, array['boiler service', 'annual service', 'service my boiler', 'boiler check', 'boiler', 'service', 'warranty']::text[]),
  ('svc_boiler_repair', 'Boiler breakdown and repair', 'heating', 'Diagnosis and repair of a faulty boiler: no heating, no hot water, error codes, pressure loss, noises or pilot light problems.', 'range', 85, 350, '£85 covers the visit, diagnosis and first hour of labour; further labour £65 per hour. Parts are extra and quoted before fitting.', 120, false, array['boiler repair', 'boiler broken', 'boiler not working', 'no heating', 'no hot water', 'error code', 'fault code', 'pressure', 'losing pressure', 'pilot light', 'boiler noise', 'noise', 'noisy', 'banging', 'kettling', 'breakdown', 'stopped working', 'boiler', 'repair', 'radiators cold']::text[]),
  ('svc_boiler_install', 'Combi boiler replacement', 'heating', 'Supply and installation of a new A-rated combi boiler, including removal of the old boiler, system flush, magnetic filter and smart-ready controls.', 'range', 2400, 3800, 'Depends on boiler model, flue position and pipework. Fixed quote given after a free survey. Up to 10-year manufacturer warranty.', 960, true, array['new boiler', 'boiler replacement', 'replace boiler', 'combi', 'combi boiler', 'boiler installation', 'install boiler', 'boiler upgrade', 'old boiler', 'boiler']::text[]),
  ('svc_system_boiler_install', 'System or regular boiler replacement', 'heating', 'Supply and installation of a new system or regular (heat-only) boiler for homes with a hot water cylinder.', 'range', 3200, 5200, 'Fixed quote given after a free survey. Cylinder replacement, if needed, is quoted separately.', 1440, true, array['system boiler', 'regular boiler', 'heat only boiler', 'conventional boiler', 'hot water tank', 'cylinder', 'boiler replacement', 'new boiler']::text[]),
  ('svc_gas_safety_cert', 'Landlord gas safety certificate (CP12)', 'gas', 'Annual landlord gas safety check of all gas appliances, flues and pipework, with the CP12 certificate emailed the same day.', 'fixed', 75, 75, '£75 per property including one appliance; £15 for each additional gas appliance.', 45, false, array['gas safety', 'gas safety certificate', 'cp12', 'landlord certificate', 'landlord', 'gas check', 'tenant', 'rental property', 'letting']::text[]),
  ('svc_gas_appliance', 'Gas hob or cooker connection', 'gas', 'Safe connection and testing of a gas hob, cooker or range cooker, including removal of the old appliance connection.', 'range', 95, 140, 'Range cookers and any new gas pipework at the higher end.', 60, false, array['gas hob', 'hob', 'cooker', 'gas cooker', 'range cooker', 'oven', 'connect cooker', 'fit hob']::text[]),
  ('svc_cylinder_service', 'Unvented hot water cylinder service', 'heating', 'Annual safety service of an unvented hot water cylinder (e.g. Megaflo), including expansion vessel and safety valve checks.', 'fixed', 120, 120, 'Fixed price per cylinder. £200 when booked together with an annual boiler service.', 60, false, array['cylinder', 'unvented', 'megaflo', 'hot water cylinder', 'hot water tank', 'expansion vessel', 'pressure relief valve']::text[]),
  ('svc_power_flush', 'Central heating power flush', 'heating', 'Power flush of the central heating system to remove sludge, with inhibitor added afterwards. Fixes cold spots and noisy radiators.', 'range', 450, 650, 'Depends on the number of radiators (up to 8 radiators at the lower end).', 480, false, array['power flush', 'powerflush', 'sludge', 'cold spots', 'radiators cold at the bottom', 'flush', 'noisy radiators', 'system clean']::text[]),
  ('svc_radiator_install', 'Radiator supply and fit', 'heating', 'Supply and fit of a new or replacement radiator, including valves and system refill.', 'range', 280, 450, 'Per radiator. Designer and column radiators quoted separately.', 180, false, array['radiator', 'new radiator', 'replace radiator', 'move radiator', 'towel rail', 'radiator valve', 'trv']::text[]),
  ('svc_smart_thermostat', 'Smart thermostat installation', 'heating', 'Supply and installation of a smart thermostat (e.g. Hive, Nest or tado), set up and connected to the customer''s phone.', 'range', 180, 320, 'Includes the thermostat; price depends on the model chosen.', 90, false, array['smart thermostat', 'thermostat', 'hive', 'nest', 'tado', 'heating controls', 'programmer', 'timer']::text[]),
  ('svc_leak_repair', 'Leak detection and repair', 'plumbing', 'Finding and fixing leaks from pipes, joints, radiators, appliances or under sinks, including small sections of replacement pipe.', 'range', 95, 280, 'Hidden leaks needing floor or wall access are at the higher end; making good of plaster or tiles is extra.', 120, false, array['leak', 'leaking', 'dripping', 'drip', 'water stain', 'damp patch', 'leaking pipe', 'water coming through ceiling', 'puddle', 'wet']::text[]),
  ('svc_burst_pipe', 'Burst or frozen pipe repair', 'plumbing', 'Repair of burst, split or frozen pipes. Outside working hours this is attended as an emergency call-out.', 'range', 120, 350, 'In working hours. Out of hours, emergency call-out rates apply.', 120, false, array['burst pipe', 'burst', 'frozen pipe', 'frozen', 'split pipe', 'pipe burst', 'flooding', 'water everywhere']::text[]),
  ('svc_blocked_drain', 'Blocked sink, toilet or drain clearance', 'plumbing', 'Clearing blocked sinks, basins, baths, toilets and internal waste pipes. External drains up to the boundary.', 'range', 90, 180, 'Jobs needing a drain camera survey are at the higher end.', 60, false, array['blocked', 'blockage', 'blocked drain', 'blocked toilet', 'blocked sink', 'slow drain', 'won''t drain', 'overflowing', 'unblock', 'drain']::text[]),
  ('svc_tap_repair', 'Tap repair or replacement', 'plumbing', 'Fixing dripping or stiff taps, or fitting new kitchen and bathroom taps (customer-supplied or ours).', 'range', 70, 160, 'Lower end for washer or cartridge repairs; higher end for replacement taps including supply.', 60, false, array['tap', 'taps', 'dripping tap', 'mixer tap', 'kitchen tap', 'new tap', 'replace tap', 'basin tap']::text[]),
  ('svc_toilet_repair', 'Toilet and cistern repair', 'plumbing', 'Repair of running or leaking toilets, faulty flushes, fill valves and cistern seals.', 'range', 75, 180, 'Replacement toilets are quoted separately.', 60, false, array['toilet', 'cistern', 'flush', 'running toilet', 'toilet keeps running', 'toilet leaking', 'fill valve', 'loo', 'wc']::text[]),
  ('svc_outside_tap', 'Outside tap installation', 'plumbing', 'Installation of an outside tap with a double check valve and isolation valve inside.', 'range', 140, 190, 'Includes the tap and fittings.', 90, false, array['outside tap', 'garden tap', 'outdoor tap', 'external tap', 'hose']::text[]),
  ('svc_shower_install', 'Shower installation', 'bathrooms', 'Installation or replacement of an electric or mixer shower. Electrical connection for electric showers by our partner electrician.', 'range', 350, 900, 'Like-for-like replacements at the lower end; new showers needing pipework, tiling or a new electrical circuit at the higher end.', 300, false, array['shower', 'electric shower', 'mixer shower', 'new shower', 'replace shower', 'shower not working', 'shower pump']::text[]),
  ('svc_bathroom_refit', 'Full bathroom refit', 'bathrooms', 'Complete bathroom design and refit: strip-out, plumbing, tiling, suite, shower or bath, and finishing.', 'range', 6500, 12000, 'Depends on room size and the suite and tiles chosen. Free design visit and fixed written quote. 25% deposit to book.', 4800, true, array['bathroom', 'bathroom refit', 'new bathroom', 'bathroom renovation', 'bathroom remodel', 'wet room', 'en suite', 'ensuite', 'refit']::text[]),
  ('svc_emergency_callout', 'Emergency call-out (24/7)', 'emergency', 'Urgent attendance for burst pipes, uncontrollable leaks, flooding, or total loss of heating or hot water in vulnerable households. Available 24 hours a day.', 'from', 120, null, '£120 call-out including the first hour; then £80 per hour. Parts extra. Same rates day or night.', 120, false, array['emergency', 'urgent', 'asap', 'right now', 'tonight', 'flooding', 'burst', 'water pouring', 'no heating', 'out of hours', 'weekend', 'callout', 'call out']::text[])
insert into policies (id, title, category, applies_to, body) values
  ('pol_callout_fees', 'Call-out and labour charges', 'fees', array['all']::text[], 'There is no separate call-out fee for appointments booked in normal working hours; the price list applies. Repair visits include the first hour of labour, then £65 per hour. Parts are quoted before fitting. All prices include VAT.'),
  ('pol_emergency', 'Emergencies and out-of-hours', 'emergency', array['all']::text[], 'We attend emergencies 24/7: burst pipes, uncontrollable leaks, flooding, no water supply, and total loss of heating or hot water where someone vulnerable (elderly, very young, or with a medical condition) is in the home. Our target is to arrive within 2 hours in the core area and within 3 hours in the extended area. Emergency call-out is £120 including the first hour, then £80 per hour. Until we arrive, turn off the water at the stopcock if it is safe to do so.'),
  ('pol_gas_safety', 'Gas smells and carbon monoxide', 'emergency', array['all']::text[], 'If you smell gas or your carbon monoxide alarm goes off: do not use switches or flames, open doors and windows, turn off the gas at the meter if you can, leave the property, and call the National Gas Emergency Service on 0800 111 999 straight away. They make the supply safe for free. We can then repair the appliance once it has been made safe.'),
  ('pol_hours', 'Opening hours', 'hours', array['all']::text[], 'Office and booked appointments: Monday to Friday 08:00-18:00 and Saturday 09:00-13:00. Closed Sundays and bank holidays except for emergencies. Appointments are offered in two-hour arrival windows.'),
  ('pol_service_area', 'Service area and travel charges', 'area', array['all']::text[], 'Core area (no travel charge): Bristol postcodes BS1 to BS16. Extended area (£25 travel charge per visit): Portishead, Clevedon, Keynsham, Bradley Stoke, Thornbury, Yate, Nailsea and nearby BS postcodes. We do not currently cover Bath (BA), Gloucestershire (GL) or Weston-super-Mare (BS22-BS24).'),
  ('pol_cancellation', 'Cancellations and missed appointments', 'cancellation', array['all']::text[], 'Appointments can be cancelled or moved free of charge up to 24 hours beforehand. Cancellations with less than 24 hours'' notice are charged £40. If our engineer cannot get access at the booked time, a £60 missed-appointment fee applies.'),
  ('pol_guarantee', 'Guarantees', 'guarantee', array['all']::text[], 'All our workmanship is guaranteed for 12 months. If a repair we carried out fails within that period, we return and fix it free of charge. New boilers carry the manufacturer''s warranty (up to 10 years) as long as they are serviced every year. Parts carry the manufacturer''s warranty.'),
  ('pol_quotes', 'Quotes and surveys', 'quotes', array['all']::text[], 'Prices on our price list are guide prices; the final price is confirmed after inspection and agreed before work starts. Boiler replacements and bathroom refits need a free, no-obligation survey, after which we send a fixed written quote valid for 30 days.'),
  ('pol_payment', 'Payment terms', 'payment', array['all']::text[], 'Payment is due on completion by card or bank transfer. Boiler installations and bathroom refits need a 25% deposit to book, with the balance due on completion. Landlords and letting agents with an account can pay invoices within 14 days.'),
  ('pol_landlords', 'Landlords and letting agents', 'landlords', array['gas']::text[], 'We arrange access directly with tenants if the landlord or agent gives us their contact details, and email the CP12 certificate to the landlord the same day. Reminders are sent 30 days before each certificate expires.'),
  ('pol_boiler_installs', 'Boiler installations', 'installations', array['heating']::text[], 'Every new boiler includes removal of the old boiler, a chemical system flush, a magnetic filter, registration with Gas Safe and the manufacturer, and the first year''s service reminder. Most combi swaps take one day; conversions from a regular to a combi boiler take two.'),
  ('pol_bathrooms', 'Bathroom projects', 'installations', array['bathrooms']::text[], 'Bathroom refits start with a free design visit. Typical refits take 7 to 10 working days. We can supply the suite and tiles or fit customer-supplied items (our 12-month workmanship guarantee applies either way).'),
  ('pol_complaints', 'Complaints', 'complaints', array['all']::text[], 'We take every complaint seriously. We acknowledge complaints within one working day, and our office manager, Claire Dunn, aims to resolve them within 10 working days. If work we did is at fault, we put it right at no cost under our guarantee.'),
  ('pol_privacy', 'Customer privacy', 'privacy', array['all']::text[], 'We only discuss a customer''s account, jobs or address with that customer (or the landlord or agent who booked the work). We never share customer details with third parties for marketing.')
